## Code Example

```c
typedef struct Block { struct Block *next; } Block;

typedef struct Pool {
  Block *head;
  unsigned int tag;
} Pool;

Block *allocate(Pool *p) {
  Block *old = p->head;
  while (old) {
    Block *next = old->next;
    if (__atomic_compare_exchange_n(&p->head, &old, next, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) {
      return old;
    }
  }
  return NULL;
}
void free_block(Pool *p, Block *b) {
  Block *old;
  do {
    old = p->head;
    b->next = old;
  } while (!__atomic_compare_exchange_n(&p->head, &old, b, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST));
}
```

